#!/usr/bin/env python3
"""Patch 36 (design step 1): Case Finding redesigned around a fit gauge; two bug fixes.
Frontend only. Run from the repository root with patches 05-35 applied. Checked against the
exact files it was written for; nothing is written unless all of it matches. Safe to re-run."""
import hashlib, os, sys
def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")
REPLACE = {'frontend/src/AskConsole.jsx': {'before': '52ff3d848ff952945f18b78722bcb8c4c8f9ea441b7f73201b398147332ac593', 'after': 'import { useRef, useState } from \'react\';\n\n// The same five for every case. Answers are read from that case\'s computed\n// fields by rule-based templates. The last is deliberately out of scope and\n// looks like any other question: clicking it shows the system declining\n// rather than guessing.\nconst SUGGESTIONS = [\n  \'What is the top candidate and why?\',\n  \'Why was the nearest vessel ruled out?\',\n  \'How confident is the release time?\',\n  \'What would change the conclusion?\',\n  \'Who is legally responsible for this spill?\',\n];\n\nexport default function AskConsole({ incidentId, api }) {\n  const [history, setHistory] = useState([]);\n  const [input, setInput] = useState(\'\');\n  const [busy, setBusy] = useState(false);\n  const scrollRef = useRef(null);\n\n  async function submit(question) {\n    if (!question.trim() || busy) return;\n    setBusy(true);\n    setInput(\'\');\n    try {\n      const result = await api.ask(incidentId, question);\n      setHistory((h) => [...h, result]);\n    } catch (e) {\n      setHistory((h) => [...h, {\n        question, intent: \'error\', supported: false,\n        answer: String(e.message ?? e), citations: [],\n      }]);\n    } finally {\n      setBusy(false);\n      requestAnimationFrame(() => {\n        // show the new answer from its first line - scrolling to the bottom hid the top of long answers\n        requestAnimationFrame(() => {\n          const box = scrollRef.current;\n          const entries = box?.querySelectorAll(\'.console-entry:not(.console-busy)\');\n          const last = entries?.[entries.length - 1];\n          if (box && last) box.scrollTo({ top: box.scrollTop + last.getBoundingClientRect().top - box.getBoundingClientRect().top - 6, behavior: \'smooth\' });\n        });\n      });\n    }\n  }\n\n  return (\n    <>\n      {history.length === 0 && (\n        <div className="suggestions-section">\n          <p>Try a question, or pick one below.</p>\n          <div className="suggestions">\n            {SUGGESTIONS.map((s) => (\n              <button key={s} className="suggestion" onClick={() => submit(s)}>{s}</button>\n            ))}\n          </div>\n        </div>\n      )}\n      <div className="console-history" ref={scrollRef}>\n        {history.map((r, i) => (\n          <div className="console-entry" key={i}>\n            <div className="console-q">&gt;&gt;&gt; {r.question}</div>\n            <div className={`console-tag ${r.supported ? \'ok\' : \'refused\'}`}>\n              {r.supported ? `answered · ${r.intent.replaceAll(\'_\', \' \')}` : \'declined · no matching template\'}\n            </div>\n            <div className="console-a">{r.answer}</div>\n            {r.citations?.length > 0 && (\n              <div className="console-cites">cites: {r.citations[0]}{r.citations.length > 1 ? ` (+${r.citations.length - 1} more)` : \'\'}</div>\n            )}\n          </div>\n        ))}\n        {busy && <div className="console-entry console-busy">running query…</div>}\n      </div>\n      <form className="console-input-row" onSubmit={(e) => { e.preventDefault(); submit(input); }}>\n        <span className="prompt">&gt;</span>\n        <input\n          value={input}\n          onChange={(e) => setInput(e.target.value)}\n          placeholder="Ask about candidates, routes, or the forcing field…"\n          disabled={busy}\n        />\n        <button type="submit" disabled={busy}>Ask</button>\n      </form>\n    </>\n  );\n}\n'}, 'frontend/src/cards/CaseFindingCard.jsx': {'before': 'fe42795f337bb762337035cf8dbe26015ccbd3e9147b65a56cc86240e84eb89f', 'after': 'import { Badge, Card } from \'../ui/primitives\';\nimport { FitGauge, HowMeasured } from \'../ui/viz\';\nimport \'./caseFinding.css\';\nimport { findingHeadline } from \'../findingText\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * The finding, stated before the evidence.\n *\n * Wording stays neutral: the proximity pick is "not supported by forward\n * replay", never "wrong" or struck through, because the interface has no\n * ground truth to call anything wrong. On an abstention it says so plainly.\n */\nexport default function CaseFindingCard({ attribution, baseline, vessels }) {\n  if (!attribution || !baseline) return null;\n\n  const nearest = baseline.ranking[0];\n  const top = attribution.ranking[0];\n  const runnerUp = attribution.ranking[1];\n  const unknown = attribution.unknown_source;\n  const nCandidates = attribution.candidates_considered.length;\n  const disc = attribution.discrimination;\n  const topVessel = vessels?.find((v) => v.vessel_key === top?.vessel_key);\n  const differs = !unknown && nearest && top && nearest.vessel_key !== top.vessel_key;\n\n  const gate = attribution.abstention_iou_gate;\n  const badge = unknown\n    ? <Badge tone="warning">System abstains</Badge>\n    : <Badge tone="accent">{differs ? \'Nearest vessel not supported\' : \'Candidate named\'}</Badge>;\n\n  const runnerIou = runnerUp?.mean_iou ?? null;\n  const wins = top?.ensemble_win_count ?? 0, nVar = top?.n_ensemble ?? 0;\n  return (\n    <Card title="Case Finding" badge={badge} className={`finding cf${unknown ? \' is-abstain\' : \'\'}`}>\n      {unknown && (\n        // A deliberate outcome, drawn as one: the statement, and every candidate\'s fit\n        // against the gate, so it is visible that none reaches it. Keyed on the\n        // system\'s own output (unknown_source), never on the case\'s family.\n        <div className="abstain-block" role="status">\n          <div className="abstain-head">\n            <svg className="abstain-mark" viewBox="0 0 20 20" aria-hidden="true">\n              <circle cx="10" cy="10" r="8" /><path d="M5.5 10h9" />\n            </svg>\n            <span>\n              <strong>The system abstains</strong>\n              <em>No candidate\'s replayed release meets the fit gate, so no vessel is named.</em>\n            </span>\n          </div>\n          <div className="gate-meter" aria-label={`Mean IoU of each replayed candidate against the fit gate of ${gate}`}>\n            <div className="gate-track">\n              <span className="gate-zone" style={{ left: `${gate * 100}%` }}><i>would be named</i></span>\n              <span className="gate-tick" style={{ left: `${gate * 100}%` }} />\n              {attribution.ranking.map((r) => (\n                <span key={r.vessel_key} className={`gate-dot${r === top ? \' is-best\' : \'\'}`}\n                      style={{ left: `${Math.max(0, Math.min(1, r.mean_iou)) * 100}%` }}\n                      title={`${r.vessel_key}: mean IoU ${r.mean_iou.toFixed(3)}`} />\n              ))}\n            </div>\n            <div className="gate-scale">\n              <span style={{ left: 0 }}>0</span>\n              <span className="is-gate" style={{ left: `${gate * 100}%` }}>gate {gate}</span>\n              <span style={{ left: \'100%\' }}>1</span>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* the abstain statement above already says it; the sentence is for a named result */}\n      {!unknown && <p className="cf-headline">{findingHeadline({ unknown, nCandidates, differs })}</p>}\n\n      {/* the comparison, as one picture: what proximity picks, then what the physics supports */}\n      <div className="cf-hero">\n        <div className={`cf-side cf-naive${differs ? \' is-struck\' : \'\'}`}>\n          <span className="cf-eyebrow">Proximity pick</span>\n          <span className="cf-key"><span>{nearest?.vessel_key}</span></span>\n          <span className="cf-sub">nearest when imaged · {nearest?.distance_deg.toFixed(3)}°</span>\n          {differs && <span className="cf-verdict">not supported by forward replay</span>}\n          {!unknown && !differs && <span className="cf-verdict is-agree">also the best physical fit</span>}\n        </div>\n        <div className="cf-bridge" aria-hidden="true">\n          <span className="cf-bridge-line" /><span className="cf-bridge-label">physics check</span><span className="cf-bridge-line" />\n        </div>\n        <div className="cf-side cf-replay">\n          <FitGauge value={top?.mean_iou ?? 0} gate={gate} secondary={unknown ? null : runnerIou}\n                    tone={unknown ? \'warning\' : \'accent\'} />\n          <div className="cf-replay-text">\n            <span className="cf-eyebrow">{unknown ? \'Forward replay · best fit\' : \'Forward replay names\'}</span>\n            <span className="cf-key is-lead">{unknown ? \'No vessel\' : top?.vessel_key}</span>\n            <span className="cf-sub">{unknown\n              ? <>best {top?.mean_iou.toFixed(2)} is below the gate of {gate}</>\n              : <>gate {gate}{runnerIou != null ? <> · runner-up {runnerIou.toFixed(2)}</> : null}</>}</span>\n            {!unknown && nVar > 0 && (\n              <span className="cf-pips" aria-label={`best under ${wins} of ${nVar} forcing variants`}>\n                {Array.from({ length: nVar }, (_, i) => <i key={i} className={i < wins ? \'is-won\' : \'\'} style={{ \'--i\': i }} />)}\n                <span>best under {wins} of {nVar} forcing variants</span>\n              </span>\n            )}\n          </div>\n        </div>\n      </div>\n\n      {!unknown && (\n        <div className="cf-chips">\n          {topVessel?.first_entry_hours_before != null && (\n            <span className="cf-chip"><i className="cf-ico is-clock" aria-hidden="true" />Inside the origin area {topVessel.first_entry_hours_before} h before</span>\n          )}\n          {disc?.discriminated === true && (\n            <span className="cf-chip"><i className="cf-ico is-gap" aria-hidden="true" />Clear of the runner-up · gap {disc.loss_gap}</span>\n          )}\n          {disc?.discriminated === false && (\n            <span className="cf-chip is-warn"><i className="cf-ico is-gap" aria-hidden="true" />Tied with the runner-up · gap {disc.loss_gap} under {disc.tolerance}</span>\n          )}\n        </div>\n      )}\n\n      <p className="cf-foot">{unknown\n        ? \'Declining is the output when no replayed release fits well enough; the source may be outside the data.\'\n        : \'A lead for an analyst, not proof of responsibility.\'}</p>\n      <HowMeasured>\n        <dl>\n          <dt>Proximity pick</dt><dd>{C.distance}</dd>\n          <dt>Mean IoU</dt><dd>{C.meanIou}</dd>\n          <dt>Fit gate</dt><dd>{C.fitGate}</dd>\n          {!unknown && <><dt>Inside the origin area</dt><dd>{C.firstEntry}</dd></>}\n          {!unknown && <><dt>Loss gap</dt><dd>{C.lossGap}</dd></>}\n          <dt>Forcing variants</dt><dd>Every release is replayed under six forcing variants; the pips count those in which this vessel fits best of all candidates.</dd>\n        </dl>\n      </HowMeasured>\n    </Card>\n  );\n}\n'}, 'frontend/src/cards/rankingReveal.css': {'before': 'c522a5d675431ac5de1dc2dfff96e17bef2f0ef1d8b778094911381ab56fe31c', 'after': '/* Naive vs forward replay: rows positioned by transform so a re-sort animates. */\n\n.rv-controls { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; margin-bottom: 14px; }\n.rv-btn {\n  height: 32px; padding: 0 14px; border: 0; border-radius: 8px; cursor: default; font: inherit;\n  font-size: var(--font-size-sm); font-weight: var(--font-weight-semibold);\n  background: var(--control-bg); color: var(--label-1); box-shadow: var(--shadow-control);\n  transition: transform var(--dur-base) var(--ease-spring), background-color var(--dur-fast) ease;\n}\n.rv-btn:hover { background: var(--control-bg-hover); }\n.rv-btn:active { transform: scale(0.97); }\n.rv-btn.is-primary { background: linear-gradient(135deg, #0a84ff, #3d9bff); color: #fff;\n                     box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.6), 0 6px 18px rgba(10, 132, 255, 0.35); }\n.rv-btn.is-primary:hover { background: linear-gradient(135deg, #2a95ff, #5aabff); }\n.rv-legend { font-size: var(--font-size-xs); color: var(--label-2); }\n\n.rv-list { position: relative; transition: height 400ms var(--ease-out); }\n.rv-row {\n  position: absolute; left: 0; right: 0; top: 0; height: 40px;\n  display: grid; grid-template-columns: 22px minmax(92px, 118px) minmax(80px, 1fr) 56px minmax(140px, 1.1fr);\n  align-items: center; gap: 12px; padding: 0 10px; border-radius: 9px;\n  transition: transform 720ms cubic-bezier(0.34, 1.26, 0.64, 1), opacity 300ms ease, background-color 300ms ease,\n              box-shadow 400ms ease, scale 400ms var(--ease-spring);\n}\n.rv-pos { font-family: var(--font-mono); font-size: var(--font-size-xs); color: var(--label-3); text-align: right; }\n.rv-key { position: relative; font-family: var(--font-mono); font-size: var(--font-size-sm); color: var(--label-1); }\n.rv-key-text { position: relative; }\n.rv-track { position: relative; height: 8px; border-radius: 4px; background: var(--fill-pressed); overflow: visible; }\n.rv-fill {\n  position: absolute; left: 0; top: 0; bottom: 0; width: calc(var(--w) * 100%); border-radius: 4px;\n  background: var(--label-3); transition: width 720ms cubic-bezier(0.34, 1.1, 0.64, 1), background-color 400ms ease;\n}\n.rv-gate { position: absolute; top: -5px; bottom: -5px; width: 2px; margin-left: -1px; border-radius: 1px;\n           background: var(--status-orange); animation: rv-in 400ms 500ms ease both; }\n.rv-value { font-family: var(--font-mono); font-size: var(--font-size-sm); font-variant-numeric: tabular-nums; text-align: right; color: var(--label-1); }\n.rv-sub { font-size: var(--font-size-xs); color: var(--label-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n\n/* before the reveal: the proximity pick */\n.rv-row.is-naive { background: rgba(255, 159, 10, 0.1); box-shadow: inset 0 0 0 0.5px rgba(255, 159, 10, 0.45); }\n.rv-row.is-naive .rv-fill { background: var(--status-orange); }\n\n/* the reveal: the proximity pick is struck through where replay does not support it */\n.rv-row.is-struck { opacity: 0.55; }\n.rv-row.is-struck .rv-key-text::after {\n  content: ""; position: absolute; left: -2px; right: -2px; top: 52%; height: 1.5px; background: var(--status-orange);\n  transform-origin: left; animation: rv-strike 360ms var(--ease-out) forwards;\n}\n.rv-row.is-struck .rv-sub { color: var(--status-orange); }\n@keyframes rv-strike { from { transform: scaleX(0); } to { transform: scaleX(1); } }\n\n/* forward replay\'s fit, and its leader */\n.rv-list .rv-row .rv-fill { background: linear-gradient(90deg, rgba(90, 200, 250, 0.55), rgba(90, 200, 250, 0.85)); }\n.rv-row.is-naive .rv-fill { background: var(--status-orange) !important; }\n.rv-row.is-out { opacity: 0.45; }\n.rv-row.is-lead { background: rgba(10, 132, 255, 0.12); box-shadow: inset 0 0 0 0.5px rgba(10, 132, 255, 0.55); }\n.rv-row.is-lead .rv-fill { background: linear-gradient(90deg, #0a84ff, #5ac8fa); }\n.rv-row.is-lead.is-settled { box-shadow: inset 0 0 0 1px rgba(10, 132, 255, 0.7), 0 0 26px rgba(10, 132, 255, 0.28);\n                              animation: rv-glow 2.6s ease-in-out 1; }\n.rv-row.is-lead .rv-key, .rv-row.is-lead .rv-value { font-weight: var(--font-weight-semibold); }\n.rv-row.is-lead .rv-sub { color: var(--accent); }\n@keyframes rv-glow { 0%, 100% { box-shadow: inset 0 0 0 1px rgba(10, 132, 255, 0.7), 0 0 14px rgba(10, 132, 255, 0.2); }\n                     40% { box-shadow: inset 0 0 0 1px rgba(10, 132, 255, 0.9), 0 0 34px rgba(10, 132, 255, 0.45); } }\n@keyframes rv-in { from { opacity: 0; } }\n\n/* when the system abstains: muted ranking, an explicit statement */\n.rv-card.is-abstain .rv-row .rv-fill { background: var(--label-3); }\n.rv-card.is-abstain .rv-row { opacity: 0.6; }\n.rv-card.is-abstain .rv-gate { box-shadow: 0 0 8px rgba(255, 159, 10, 0.8); }\n.rv-abstain { display: flex; flex-direction: column; gap: 4px; margin-top: 14px; padding: 12px 14px; border-radius: 10px;\n              background: rgba(255, 159, 10, 0.1); box-shadow: inset 0 0 0 0.5px rgba(255, 159, 10, 0.5);\n              font-size: var(--font-size-sm); color: var(--label-1); animation: rv-in 400ms 600ms ease both; }\n.rv-abstain strong { color: var(--status-orange); }\n.rv-note { margin: 14px 0 0; font-size: var(--font-size-sm); color: var(--label-2); animation: rv-in 400ms ease both; }\n\n@media (prefers-reduced-motion: reduce) {\n  .rv-row, .rv-fill, .rv-list { transition: none; }\n  .rv-row.is-struck .rv-key-text::after, .rv-row.is-lead.is-settled, .rv-gate, .rv-abstain, .rv-note { animation: none; }\n}\n@media (max-width: 760px) { .rv-row { grid-template-columns: 18px 92px 1fr 50px; } .rv-sub { display: none; } }\n\n/* a row reached from the map flashes once */\n.rv-row.is-flash { animation: row-flash 1.8s var(--ease-out); }\n'}}
NEW = {'frontend/src/cards/caseFinding.css': '/* Case Finding: one sentence, then the comparison as one picture. */\n.cf-headline { margin: 0 0 var(--space-5); font-family: var(--font-display); font-size: 19px; line-height: 1.35;\n               font-weight: 500; letter-spacing: -0.012em; color: var(--label-1); max-width: 42ch; }\n.cf-hero { display: grid; grid-template-columns: minmax(0, 0.9fr) auto minmax(0, 1.25fr); align-items: center; gap: var(--space-5); }\n.cf-side { display: flex; flex-direction: column; gap: 4px; min-width: 0; }\n.cf-eyebrow { font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase;\n              letter-spacing: 0.07em; color: var(--label-2); }\n.cf-key { position: relative; align-self: flex-start; font-family: var(--font-mono); font-size: 22px; font-weight: 500;\n          letter-spacing: -0.01em; color: var(--label-1); }\n.cf-key > span { position: relative; }\n.cf-key.is-lead { font-size: 26px; font-weight: 600; background: linear-gradient(90deg, #0a84ff, #64d2ff);\n                  -webkit-background-clip: text; background-clip: text; color: transparent; }\n.cf.is-abstain .cf-key.is-lead { background: none; color: var(--status-orange); font-family: var(--font-display); }\n.cf-sub { font-size: var(--font-size-xs); color: var(--label-2); }\n.cf-verdict { margin-top: 6px; align-self: flex-start; padding: 2px 9px; border-radius: 999px; font-size: var(--font-size-xxs);\n              font-weight: var(--font-weight-semibold); color: var(--status-orange); background: rgba(255, 159, 10, 0.12); }\n.cf-verdict.is-agree { color: var(--status-green); background: rgba(48, 209, 88, 0.12); }\n\n/* the proximity pick, set aside where the physics disagrees */\n.cf-naive.is-struck .cf-key { color: var(--label-2); }\n.cf-naive.is-struck .cf-key > span::after {\n  content: ""; position: absolute; left: -3px; right: -3px; top: 54%; height: 2px; border-radius: 1px; background: var(--status-orange);\n  transform-origin: left; animation: cf-strike 520ms 700ms cubic-bezier(0.22, 1, 0.36, 1) backwards;\n}\n@keyframes cf-strike { from { transform: scaleX(0); } }\n\n/* the bridge between them */\n.cf-bridge { display: flex; align-items: center; gap: 8px; color: var(--label-3); }\n.cf-bridge-line { width: 26px; height: 1px; background: linear-gradient(90deg, transparent, var(--label-3)); }\n.cf-bridge-line:last-child { background: linear-gradient(90deg, var(--label-3), transparent); }\n.cf-bridge-label { font-size: var(--font-size-xxs); text-transform: uppercase; letter-spacing: 0.08em; white-space: nowrap; }\n\n/* forward replay\'s pick: the gauge and what it says */\n.cf-replay { flex-direction: row; align-items: center; gap: var(--space-4); padding: 14px 16px; border-radius: 16px;\n             background: linear-gradient(135deg, rgba(10, 132, 255, 0.1), rgba(100, 210, 255, 0.04));\n             box-shadow: inset 0 0 0 0.5px rgba(10, 132, 255, 0.35); }\n.cf.is-abstain .cf-replay { background: linear-gradient(135deg, rgba(255, 159, 10, 0.1), rgba(255, 214, 10, 0.03));\n                            box-shadow: inset 0 0 0 0.5px rgba(255, 159, 10, 0.4); }\n.cf-replay-text { display: flex; flex-direction: column; gap: 4px; min-width: 0; }\n.cf-pips { display: flex; align-items: center; gap: 4px; margin-top: 6px; font-size: var(--font-size-xxs); color: var(--label-2); }\n.cf-pips i { width: 8px; height: 8px; border-radius: 50%; background: var(--fill-pressed);\n             animation: cf-pip 420ms cubic-bezier(0.34, 1.56, 0.64, 1) backwards; animation-delay: calc(900ms + var(--i) * 70ms); }\n.cf-pips i.is-won { background: #64d2ff; box-shadow: 0 0 6px rgba(100, 210, 255, 0.7); }\n.cf-pips span { margin-left: 6px; }\n@keyframes cf-pip { from { transform: scale(0); } }\n\n/* the supporting facts, as chips */\n.cf-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: var(--space-5); }\n.cf-chip { display: inline-flex; align-items: center; gap: 7px; padding: 5px 11px; border-radius: 999px; font-size: var(--font-size-xs);\n           color: var(--label-1); background: var(--fill-pressed); }\n.cf-chip.is-warn { color: var(--status-orange); background: rgba(255, 159, 10, 0.12); }\n.cf-ico { width: 12px; height: 12px; border-radius: 50%; border: 1.5px solid currentColor; opacity: 0.7; position: relative; }\n.cf-ico.is-clock::after { content: ""; position: absolute; left: 4px; top: 1.5px; width: 3px; height: 4px;\n                          border-left: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor; }\n.cf-ico.is-gap { border-radius: 2px; border-width: 0 1.5px; height: 10px; }\n.cf-foot { margin: var(--space-4) 0 0; font-size: var(--font-size-sm); color: var(--label-2); }\n\n@media (max-width: 900px) { .cf-hero { grid-template-columns: 1fr; } .cf-bridge { display: none; } }\n@media (prefers-reduced-motion: reduce) { .cf-naive.is-struck .cf-key > span::after, .cf-pips i { animation: none; } }\n', 'frontend/src/ui/useCountUp.js': "import { useEffect, useRef, useState } from 'react';\n\nconst reduce = () => typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n/**\n * A number that counts up to its value when it first appears. Under reduced\n * motion, or with no value, it simply shows the value.\n */\nexport function useCountUp(value, { duration = 900, decimals = 2 } = {}) {\n  const still = reduce() || value == null;\n  const [shown, setShown] = useState(0);\n  const from = useRef(0);\n  useEffect(() => {\n    if (still) return undefined;\n    let raf = 0;\n    const start = performance.now(), a = from.current;\n    const tick = (t) => {\n      const k = Math.min(1, (t - start) / duration), e = 1 - Math.pow(1 - k, 3);\n      setShown(a + (value - a) * e);\n      if (k < 1) raf = requestAnimationFrame(tick); else from.current = value;\n    };\n    raf = requestAnimationFrame(tick);\n    return () => cancelAnimationFrame(raf);\n  }, [value, duration, still]);\n  if (value == null) return '—';\n  return Number(still ? value : shown).toFixed(decimals);\n}\n", 'frontend/src/ui/viz.css': '/* fit gauge */\n.fitg { position: relative; flex: none; }\n.fitg svg { width: 100%; height: 100%; overflow: visible; }\n.fitg-track { fill: none; stroke: var(--fill-pressed); stroke-width: 9; stroke-linecap: round; }\n.fitg-arc { fill: none; stroke-width: 9; stroke-linecap: round; transition: stroke-dasharray 1100ms cubic-bezier(0.22, 1, 0.36, 1);\n            filter: drop-shadow(0 0 6px rgba(10, 132, 255, 0.45)); }\n.fitg.is-warning .fitg-arc { filter: drop-shadow(0 0 6px rgba(255, 159, 10, 0.45)); }\n.fitg-gate { stroke: var(--status-orange); stroke-width: 2.4; stroke-linecap: round; }\n.fitg-sec { fill: var(--label-3); stroke: var(--card-bg, var(--content-bg)); stroke-width: 1.5; }\n.fitg-center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }\n.fitg-num { font-family: var(--font-display); font-size: 30px; font-weight: 600; letter-spacing: -0.02em;\n            font-variant-numeric: tabular-nums; color: var(--label-1); }\n.fitg-label { margin-top: -2px; font-size: var(--font-size-xxs); color: var(--label-2); text-transform: uppercase; letter-spacing: 0.06em; }\n@media (prefers-reduced-motion: reduce) { .fitg-arc { transition: none; } }\n\n/* "How this is measured" */\n.howto { margin-top: var(--space-4); border-top: 0.5px solid var(--separator); padding-top: var(--space-3); }\n.howto summary { display: inline-flex; align-items: center; gap: 7px; cursor: default; list-style: none;\n                 font-size: var(--font-size-xs); font-weight: var(--font-weight-medium); color: var(--label-2);\n                 border-radius: 6px; padding: 2px 4px; margin-left: -4px; transition: color var(--dur-fast) ease; }\n.howto summary::-webkit-details-marker { display: none; }\n.howto summary:hover { color: var(--label-1); }\n.howto summary:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: 1px; }\n.howto-chev { width: 7px; height: 7px; border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor;\n              transform: rotate(-45deg); transition: transform 240ms var(--ease-spring); }\n.howto[open] .howto-chev { transform: rotate(45deg); }\n.howto-body { margin-top: 10px; display: grid; gap: 8px; font-size: var(--font-size-xs); line-height: 1.5; color: var(--label-2);\n              animation: howto-in 280ms var(--ease-out); }\n.howto-body dt { color: var(--label-1); font-weight: var(--font-weight-semibold); }\n.howto-body dd { margin: 0 0 4px; }\n@keyframes howto-in { from { opacity: 0; translate: 0 -4px; } }\n', 'frontend/src/ui/viz.jsx': 'import { useEffect, useState } from \'react\';\nimport { useCountUp } from \'./useCountUp\';\nimport \'./viz.css\';\n\n/**\n * Shared visual primitives: a fit gauge, a count-up number, and the disclosure\n * that holds method notes. Every value they show is passed in from an artifact;\n * they only draw it.\n */\nconst reduce = () => typeof window !== \'undefined\' && window.matchMedia(\'(prefers-reduced-motion: reduce)\').matches;\n\n/**\n * A 270° ring for a 0-1 fit: the arc draws in to the value; a tick marks the\n * gate below which no vessel is named, and a dot marks the runner-up.\n */\nexport function FitGauge({ value, gate, secondary = null, tone = \'accent\', size = 132, label = \'mean IoU\' }) {\n  const [drawn, setDrawn] = useState(reduce());\n  useEffect(() => { const id = requestAnimationFrame(() => setDrawn(true)); return () => cancelAnimationFrame(id); }, []);\n  const n = useCountUp(value, { decimals: 2 });\n  const r = 46, c = 2 * Math.PI * r, span = 0.75;                 // 270° of the circle\n  const at = (f) => {                                              // angle along the arc for a fraction\n    const a = (135 + 270 * Math.max(0, Math.min(1, f))) * Math.PI / 180;\n    return [60 + r * Math.cos(a), 60 + r * Math.sin(a)];\n  };\n  const [gx, gy] = at(gate), [gx2, gy2] = [60 + (r + 9) * Math.cos((135 + 270 * gate) * Math.PI / 180), 60 + (r + 9) * Math.sin((135 + 270 * gate) * Math.PI / 180)];\n  const [gx1, gy1] = [60 + (r - 9) * Math.cos((135 + 270 * gate) * Math.PI / 180), 60 + (r - 9) * Math.sin((135 + 270 * gate) * Math.PI / 180)];\n  const sec = secondary != null ? at(secondary) : null;\n  return (\n    <div className={`fitg is-${tone}`} style={{ width: size, height: size }}\n         role="img" aria-label={`${label} ${value?.toFixed(2)}, fit gate ${gate}${secondary != null ? `, runner-up ${secondary.toFixed(2)}` : \'\'}`}>\n      <svg viewBox="0 0 120 120" aria-hidden="true">\n        <defs>\n          <linearGradient id={`fitg-${tone}`} x1="0" y1="1" x2="1" y2="0">\n            <stop offset="0" stopColor={tone === \'accent\' ? \'#0a84ff\' : \'#ff9f0a\'} />\n            <stop offset="1" stopColor={tone === \'accent\' ? \'#64d2ff\' : \'#ffd60a\'} />\n          </linearGradient>\n        </defs>\n        <circle cx="60" cy="60" r={r} className="fitg-track" strokeDasharray={`${c * span} ${c}`} transform="rotate(135 60 60)" />\n        <circle cx="60" cy="60" r={r} className="fitg-arc" stroke={`url(#fitg-${tone})`} transform="rotate(135 60 60)"\n                strokeDasharray={`${c * span * (drawn ? Math.max(0, Math.min(1, value ?? 0)) : 0)} ${c}`} />\n        <line x1={gx1} y1={gy1} x2={gx2} y2={gy2} className="fitg-gate" />\n        {sec && <circle cx={sec[0]} cy={sec[1]} r="3.4" className="fitg-sec" />}\n        <circle cx={gx} cy={gy} r="0" />\n      </svg>\n      <div className="fitg-center">\n        <span className="fitg-num">{n}</span>\n        <span className="fitg-label">{label}</span>\n      </div>\n    </div>\n  );\n}\n\n/** Method notes and definitions, folded away until asked for. */\nexport function HowMeasured({ children, title = \'How this is measured\' }) {\n  return (\n    <details className="howto">\n      <summary><span className="howto-chev" aria-hidden="true" />{title}</summary>\n      <div className="howto-body">{children}</div>\n    </details>\n  );\n}\n'}
CL_OLD = "the card's colour. Motion is off under reduced-motion settings.\n"
CL_NEW = 'the card\'s colour. Motion is off under reduced-motion settings.\n\n**Design step 1: Case Finding as one sentence and one picture.** The card leads with its\nfinding, then the comparison as a visual: the proximity pick, struck through where forward\nreplay disagrees, against forward replay\'s pick with a fit gauge that draws in to its mean\nIoU (gate and runner-up marked) and pips for the forcing variants it won. Supporting facts are\nchips; definitions fold into "How this is measured". Shared viz primitives (gauge, count-up,\ndisclosure) are added for the next steps. Fixed: the reveal\'s leader row no longer scales out\nof line, and Ask shows each answer from its first line.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text: skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 35 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
